import { z } from 'zod';

export const paymentMethodSchema = z.enum(['COD', 'ONLINE']);
export type CheckoutPaymentMethod = z.infer<typeof paymentMethodSchema>;

// Generated by the checkout page once per attempt and repeated unchanged on every retry (plan C29).
export const checkoutIdempotencyKeySchema = z.string().regex(/^[A-Za-z0-9_-]{16,100}$/);

export const placeOrderSchema = z.strictObject({
  addressId: z.uuid().transform((value) => value.toLowerCase()),
  paymentMethod: paymentMethodSchema,
  expectedTotalPaise: z.int().min(0).max(1_000_000_000),
});
export type PlaceOrderInput = z.infer<typeof placeOrderSchema>;

export const checkoutSummaryQuerySchema = z.object({
  addressId: z
    .uuid()
    .transform((value) => value.toLowerCase())
    .optional(),
  paymentMethod: paymentMethodSchema.default('COD'),
});
